identityAttestation:
begin isolation level repeatable read read only; set local statement_timeout='3s'; set local lock_timeout='500ms';
with ids as materialized (select fabric_id from curtainsuk_private.fabric_colourways order by fabric_id limit 20001)
select current_timestamp as observed_at,pg_current_snapshot()::text as mvcc_snapshot,count(*)::int as identity_count,count(*)<20001 as inventory_complete,encode(sha256(convert_to(string_agg(fabric_id,E'\n' order by fabric_id),'UTF8')),'hex') as identity_sha256 from ids; rollback;
